mapper.select:
SELECT d.document_id, d.document_name, d.document_type, d.content_source, l.tenant_id, l.space_id, NULL AS "fileIcon", l.library_id, p.created_time AS "shareTime", d.updated_time AS "lastModifiedTime", p.permission_type AS "permissions", p.granted_by AS "sharerUserId", CASE WHEN EXISTS (SELECT 1 FROM bt_dc_user_favorite uf WHERE uf.target_id = d.document_id AND uf.target_type = 'DOCUMENT' AND uf.user_id = #{userId} AND uf.status_cd = '00A') THEN 1 ELSE 0 END AS "isFavorite", CASE WHEN EXISTS (SELECT 1 FROM bt_dc_user_homepage_pin uhp WHERE uhp.target_id = d.document_id AND uhp.target_type = 'DOCUMENT' AND uhp.user_id = #{userId} AND uhp.status_cd = '00A') THEN 1 ELSE 0 END AS "isPinned", CASE WHEN EXISTS ( SELECT 1 FROM bt_dc_document_library lib WHERE lib.library_id = d.library_id AND lib.visibility_scope = 'PRIVATE' AND lib.is_builtin = 'T' AND lib.library_name = '我的文档' AND lib.status_cd = '00A' ) THEN 'T' ELSE 'F' END AS "myDoc" FROM bt_dc_document_permission p JOIN bt_dc_document d ON p.document_id = d.document_id JOIN bt_dc_document_library l ON d.library_id = l.library_id WHERE p.status_cd = '00A' AND d.status_cd = '00A'
AND l.tenant_id = #{tenantId} AND d.tenant_id = #{tenantId}
AND l.space_id = #{spaceId} AND d.space_id = #{spaceId}
AND l.status_cd = '00A' AND p.subject_type = 'USER' AND p.subject_id = #{userId}
AND d.document_type IN ('WORD', 'WORD_ONLINE')
AND d.document_type IN ('EXCEL', 'EXCEL_ONLINE')
AND d.document_type = #{fileType}
ORDER BY d.updated_time ASC
ORDER BY d.updated_time DESC
ORDER BY p.created_time ASC
ORDER BY p.created_time DESC

SELECT d.document_id, d.document_name, d.document_type, d.content_source, l.tenant_id, l.space_id, NULL AS "fileIcon", l.library_id, MAX(p.created_time) AS "shareTime", d.updated_time AS "lastModifiedTime", CASE WHEN EXISTS (SELECT 1 FROM bt_dc_user_favorite uf WHERE uf.target_id = d.document_id AND uf.target_type = 'DOCUMENT' AND uf.user_id = #{userId} AND uf.status_cd = '00A') THEN 1 ELSE 0 END AS "isFavorite", CASE WHEN EXISTS (SELECT 1 FROM bt_dc_user_homepage_pin uhp WHERE uhp.target_id = d.document_id AND uhp.target_type = 'DOCUMENT' AND uhp.user_id = #{userId} AND uhp.status_cd = '00A') THEN 1 ELSE 0 END AS "isPinned", MAX(CASE WHEN l.visibility_scope = 'PRIVATE' AND l.is_builtin = 'T' AND l.library_name = '我的文档' THEN 'T' ELSE 'F' END) AS "myDoc" FROM bt_dc_document_permission p JOIN bt_dc_document d ON p.document_id = d.document_id JOIN bt_dc_document_library l ON d.library_id = l.library_id WHERE p.status_cd = '00A' AND d.status_cd = '00A' AND l.status_cd = '00A'
AND l.tenant_id = #{tenantId} AND d.tenant_id = #{tenantId}
AND l.space_id = #{spaceId} AND d.space_id = #{spaceId}
AND p.granted_by = #{userId}
AND d.document_type IN ('WORD', 'WORD_ONLINE')
AND d.document_type IN ('EXCEL', 'EXCEL_ONLINE')
AND d.document_type = #{fileType}
GROUP BY d.document_id, d.document_name, d.document_type, d.content_source, l.library_id, d.updated_time, l.tenant_id, d.tenant_id, l.space_id, d.space_id
ORDER BY d.updated_time ASC
ORDER BY d.updated_time DESC
ORDER BY MAX(p.created_time) ASC
ORDER BY MAX(p.created_time) DESC

SELECT p.subject_id AS "subjectId", p.subject_type AS "subjectType", p.permission_type AS "permissionType", p.document_id AS "documentId", p.created_time AS "createdTime" FROM bt_dc_document_permission p WHERE p.status_cd = '00A' AND p.granted_by = #{userId} AND p.document_id IN
#{documentId}
ORDER BY p.document_id, p.created_time DESC
